                }
            }

            while ($end >= $start) {
                $character = $subject[$end];
                $code = ord($character);

                if ($code === 0x20) {
                    $end--;
                } elseif ($code === 0x09) {
                    $end--;
                } elseif ($code === 0x0A) {
                    $end--;
                } elseif ($code === 0x0B) {
                    $end--;
                } elseif ($code === 0x0C) {
                    $end--;
